// Написан вручную (две роли — генератор не умеет), не проверен на живой странице — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/location-map.md 2.5 · кейс .qa/tests/location-map/IND-05.md
// Геолокация эмулируется; Date Now не включается; в конце шаринг выключается у обеих ролей, сессии сохраняются (одноразовый refresh-токен).
import { test, expect } from '../../fixtures';
import { setupMapUser, enableSharing, disableSharing, openMap, expectInNearby, userIdOf } from './map-helpers';
import { saveSession } from '../_shared/session';

test.describe('Индикатор шаринга местоположения', () => {
  test.describe.configure({ timeout: 240_000 }); // две роли + ожидание опроса карты у наблюдателя (#0f19c0)
  test('Выключение с индикатора — у наблюдателя user4 free пропадает с карты @iphone @data (#5f64d4)', async ({ asUser }) => {
    const free = await asUser('free');
    const user4 = await asUser('user4');
    await setupMapUser(free, 'free');
    await setupMapUser(user4, 'user4');
    const freeId = userIdOf('free');
    try {
      // Предусловие: оба шарят, user4 видит free.
      await enableSharing(user4);
      await enableSharing(free);
      await openMap(user4);
      await expectInNearby(user4, freeId, true);

      // free выключает прямо с индикатора (AC 3): пилюля → «לכבות את שיתוף המיקום?» → «כיבוי שיתוף מיקום».
      await disableSharing(free);
      // У себя сразу: пилюли нет, карточка «שיתוף מיקום כבוי» (AC 2).
      await expect(free.getByText('שיתוף מיקום פעיל')).toHaveCount(0);
      await expect(free.getByText('שיתוף מיקום כבוי')).toBeVisible();

      // У наблюдателя free пропадает из nearby_live (опрос с перезагрузкой, до 60 с; задержка — реджект #0f19c0).
      await expectInNearby(user4, freeId, false);
    } finally {
      await disableSharing(free).catch(() => {});
      await disableSharing(user4).catch(() => {});
      await saveSession(free, 'free');
      await saveSession(user4, 'user4');
    }
  });
});
